action.code:
if (!r) {
    r = new Node<T>(item);
} else {
    if (item < r->value)
        _insert(r->left, item);
    else if (item > r->value)
        _insert(r->right, item);
    else
        return; // Duplicate items not allowed
}

r->bFactor = _getBalance(r);

if (r->bFactor > 1) {
    if (_getBalance(r->left) >= 0)
        _rotateRight(r);
    else {
        _rotateLeft(r->left);
        _rotateRight(r);
    }
} else if (r->bFactor < -1) {
    if (_getBalance(r->right) <= 0)
        _rotateLeft(r);
    else {
        _rotateRight(r->right);
        _rotateLeft(r);
    }
}

_updatebFactors(r);

